svg.script:
(function(){
  var a1 = document.getElementById('atom1');
  var a2 = document.getElementById('atom2');
  var a3 = document.getElementById('atom3');
  var win = (typeof window !== 'undefined' && window.parent && window.parent !== window) ? window.parent : window;
  var rot = 0, lastY = win.scrollY || 0, raf = null;
  win.addEventListener('scroll', function(){
    if (raf) cancelAnimationFrame(raf);
    raf = requestAnimationFrame(function(){
      var y = win.scrollY || 0;
      rot += (y - lastY);
      lastY = y;
      a1.style.transform = 'rotate(' + (rot * 0.5) + 'deg)';
      a2.style.transform = 'rotate(' + (rot * -0.85) + 'deg)';
      a3.style.transform = 'rotate(' + (rot * 1.3) + 'deg)';
    });
  }, { passive: true });
})();
